0,0.05);\n  transition: background 0.15s, border-color 0.15s;\n}\n\n.btn-cv-view[_ngcontent-%COMP%]:hover:not(.disabled-button) {\n  background: #f8fafc;\n  border-color: #94a3b8;\n}\n\n.disabled-button[_ngcontent-%COMP%] {\n  opacity: 0.55 !important;\n  cursor: not-allowed !important;\n}\n\n.candidate-main-info[_ngcontent-%COMP%] {\n  flex-grow: 1;\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n}\n\n.candidate-summary-grid[_ngcontent-%COMP%] {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n  width: 100%;\n}\n\n.candidate-summary-item[_ngcontent-%COMP%], \n.candidate-main-line[_ngcontent-%COMP%], \n.candidate-detail-item[_ngcontent-%COMP%] {\n  display: flex;\n  justify-content: space-between;\n  gap: 14px;\n  align-items: flex-start;\n}\n\n.info-label[_ngcontent-%COMP%], \n.detail-label[_ngcontent-%COMP%] {\n  color: #475569;\n  font-size: 13px;\n  font-weight: 700;\n  min-width: 130px;\n}\n\n.info-value[_ngcontent-%COMP%], \n.detail-value[_ngcontent-%COMP%] {\n  color: #0f172a;\n  font-size: 13px;\n  text-align: right;\n  display: block;\n  flex: 1;\n}\n\n.candidate-detail-grid[_ngcontent-%COMP%] {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 16px;\n  margin-bottom: 16px;\n}\n\n.candidate-detail-item[_ngcontent-%COMP%] {\n  background: #f8fafc;\n  border: 1px solid #e2e8f0;\n  border-radius: 12px;\n  padding: 14px 16px;\n}\n\n.network-separator[_ngcontent-%COMP%] {\n  color: #cbd5e1;\n  margin: 0 8px;\n}\n\n.detail-empty[_ngcontent-%COMP%] {\n  color: #94a3b8;\n  font-style: italic;\n}\n\n.summary-box[_ngcontent-%COMP%] {\n  margin-top: 15px;\n  padding: 16px;\n  background: #f8fafc;\n  border-radius: 8px;\n  border-left: 4px solid #0ea5e9;\n}\n\n.modal-header[_ngcontent-%COMP%] {\n  padding: 20px 24px;\n  border-bottom: 1px solid #f1f5f9;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  background-color: #ffffff;\n}\n\n.modal-header[_ngcontent-%CO