 border: 1px solid #e9d5ff;\n  border-radius: 8px;\n  padding: 10px 12px;\n}\n\n.notif-quiz-item.correct[_ngcontent-%COMP%] {\n  border-left: 4px solid #10b981;\n}\n\n.notif-quiz-item.incorrect[_ngcontent-%COMP%] {\n  border-left: 4px solid #f59e0b;\n}\n\n.notif-quiz-question[_ngcontent-%COMP%] {\n  font-size: 12.5px;\n  font-weight: 600;\n  color: #334155;\n  margin-bottom: 6px;\n}\n\n.notif-quiz-number[_ngcontent-%COMP%] {\n  display: inline-block;\n  padding: 2px 8px;\n  border-radius: 4px;\n  background: #f3e8ff;\n  color: #7c3aed;\n  font-size: 11px;\n  font-weight: 700;\n  margin-right: 8px;\n}\n\n.notif-quiz-answer[_ngcontent-%COMP%] {\n  font-size: 12.5px;\n  color: #475569;\n}\n\n.notif-quiz-empty[_ngcontent-%COMP%] {\n  margin: 0;\n  padding: 0 14px 14px;\n  font-size: 12.5px;\n  color: #64748b;\n  font-style: italic;\n}\n\n/*# sourceMappingURL=data:application/json;charset=utf-8;base64, */"]
