import { Component, inject, OnInit, OnDestroy, ChangeDetectorRef, NgZone } from '@angular/core';
import { RouterOutlet, RouterLink, RouterLinkActive, Router } from '@angular/router';
import { CommonModule, NgIf } from '@angular/common'; 
import { NotificationCenterComponent } from '../../../shared/components/notification-center/notification-center.component';
import { NotificationService } from '../../../core/services/notification.service';
import { Subscription } from 'rxjs';
import { environment } from '../../../../environments/environment';


@Component({
  selector: 'app-recruiter-layout',
  standalone: true,
  imports: [RouterOutlet, RouterLink, RouterLinkActive, CommonModule, NgIf, NotificationCenterComponent], 
  templateUrl: './recruiter-layout.component.html',
  styleUrls: ['./recruiter-layout.component.css'] 
})
export class RecruiterLayoutComponent implements OnInit, OnDestroy {
  private router = inject(Router);
  private notificationService = inject(NotificationService);
  private cdr = inject(ChangeDetectorRef);
  private zone = inject(NgZone); 
  
  recruiterName = 'Recruteur';
  assetsUrl = environment.assetsUrl;
  selectedDirectCandidate: any = null;
  
  // 🏢 L'état du badge passe par cette variable mise à jour par l'API
  isVerifiedCompany = false;
  
  private notifSubscription: Subscription | null = null;

  ngOnInit() {
    const storedName = localStorage.getItem('name');
    if (storedName) {
      this.recruiterName = storedName;
    }

    // 🚀 FIX CHIRURGICAL : Plus de localStorage. On interroge directement MySQL au chargement
    this.checkRealtimeVerification();

    // 🚀 LIAISON SÉCURISÉE AVEC RÉINITIALISATION DYNAMIQUE DU CANDIDAT
    this.notifSubscription = this.notificationService.openApplication$.subscribe(candidateObject => {
      if (!candidateObject) {
        this.zone.run(() => {
          this.selectedDirectCandidate = null;
          this.cdr.detectChanges();
        });
        return;
      }

      console.log("📥 Layout global - Reçu l'objet pour affichage de la popup :", candidateObject);
      
      this.zone.run(() => {
        // A. On vide d'abord l'ancien profil pour forcer le rafraîchissement d'Angular
        this.selectedDirectCandidate = null;
        this.cdr.detectChanges();

        // B. On injecte immédiatement le nouveau candidat chargé de MySQL
        this.selectedDirectCandidate = candidateObject; 
        this.cdr.detectChanges(); 
      });
    });
  }

  // 📡 SYNCHRONISATION EN DIRECT PAR API : Cherche la valeur fraîche dans votre table users
  checkRealtimeVerification() {
    const token = localStorage.getItem('token');
    fetch(`${environment.apiUrl}/auth/profile`, {
      method: 'GET',
      headers: { 
        'Authorization': token ? `Bearer ${token}` : '' 
      }
    })
    .then(res => res.json())
    .then(user => {
      // Met à jour la variable avec le vrai état de votre table MySQL (0 ou 1)
      this.isVerifiedCompany = user.is_verified_company === 1;
      this.cdr.detectChanges(); // Force le rafraîchissement visuel du menu
    })
    .catch(err => console.error("❌ Erreur de synchronisation du statut recruteur :", err));
  }

  changeCandidateStatus(applicationId: number, newStatus: string) {
    if (!applicationId) return;
    
    const targetUrl = `${environment.apiUrl}/recruiter/ats/update-status`;
    const token = localStorage.getItem('token');

    fetch(targetUrl, {
      method: 'POST',
      headers: { 
        'Content-Type': 'application/json',
        'Authorization': token ? `Bearer ${token}` : '' 
      },
      body: JSON.stringify({ id: applicationId, status: newStatus })
    })
    .then(res => {
      if (!res.ok) throw new Error("Échec de la mise à jour du statut.");
      return res.json();
    })
    .then(() => {
      console.log(`✅ Statut mis à jour avec succès : ${newStatus}`);
      this.closeModal(); 
    })
    .catch(err => console.error("❌ Erreur de traitement du changement de statut :", err));
  }

  openCandidateCV(candidateId: number) {
    if (!candidateId) return;
    window.open(`/candidate/cv-view/${candidateId}`, '_blank');
  }

  // 🚀 ACTION DE FERMETURE : Supprime les données en mémoire du service et du composant
  closeModal() {
    this.zone.run(() => {
      this.selectedDirectCandidate = null;
      this.notificationService.clearTrigger(); // Demande au service d'émettre 'null'
      this.cdr.detectChanges();
    });
  }

  ngOnDestroy() {
    if (this.notifSubscription) {
      this.notifSubscription.unsubscribe();
    }
    this.notificationService.clearTrigger();
  }

  onLogout() {
    localStorage.clear();
    this.router.navigate(['/login']);
  }
}
<div class="app-container">
  
  <!-- 🧭 SIDEBAR COMPLÈTE & PROFESSIONNELLE SÉCURISÉE -->
  <aside class="app-sidebar">
    <div class="sidebar-brand">
      <div class="logo-icon"><i class="bi bi-rocket-takeoff-fill"></i></div>
      <div class="logo-text">Tun<span>Job</span> Pro</div>
    </div>

    <!-- 👤 BLOC PROFIL DYNAMIQUE UNIQUE : Connecté au statut de modération Admin -->
    <div class="recruiter-profile-summary">
      <div class="avatar-circle"><i class="bi bi-building-fill"></i></div>
      <div class="profile-info">
        <h4 class="company-name">{{ recruiterName }}</h4>
        
        <!-- 🔄 Bascule d'affichage en temps réel (Vert si vérifié, Orange si en attente) -->
        @if (isVerifiedCompany) {
          <span class="badge-status">
            <span class="dot"></span> Compte Vérifié
          </span>
        } @else {
          <span class="badge-status-pending">
            <span class="dot"></span> En attente
          </span>
        }
      </div>
    </div>

    <nav class="sidebar-nav">
      <div class="nav-section-title">Recrutement</div>
      
      <a routerLink="/recruiter" routerLinkActive="active" [routerLinkActiveOptions]="{exact: true}" class="nav-link-item">
        <i class="bi bi-grid-1x2-fill"></i> Vue d'ensemble
      </a>
      
      <a routerLink="/recruiter/create-job" routerLinkActive="active" class="nav-link-item">
        <i class="bi bi-plus-circle-fill"></i> Publier une offre
      </a>
      
      <a routerLink="/recruiter/job-manage" routerLinkActive="active" class="nav-link-item">
        <i class="bi bi-briefcase-fill"></i> Gérer mes annonces
      </a>
      
      <a routerLink="/recruiter/ats-pipeline" routerLinkActive="active" class="nav-link-item">
        <i class="bi bi-people-fill"></i> Suivi Candidats (ATS)
        <span class="nav-badge">14</span>
      </a>

      <div class="nav-section-title">Entreprise & Paramètres</div>
      
      <a routerLink="/recruiter/profile-settings" routerLinkActive="active" class="nav-link-item">
        <i class="bi bi-sliders"></i> Configuration Profil & Logo
      </a>

      <a (click)="onLogout()" class="nav-link-item logout-item" style="cursor: pointer;">
        <i class="bi bi-box-arrow-left"></i> Quitter la session
      </a>
    </nav>
  </aside>

  <!-- 💻 ZONE DE CONTENU PRINCIPALE DYNAMIQUE -->
  <main class="app-main">
    <header class="app-header">
      <div class="header-welcome">
        <h2>Bienvenue, <span class="highlight">{{ recruiterName }}</span> 👋</h2>
        <p>Voici l'état actuel de vos campagnes de recrutement en Tunisie.</p>
      </div>

      <div class="header-actions">
        <button routerLink="/recruiter/create-job" class="btn-quick-add">
          <i class="bi bi-plus"></i> Nouvelle Annonce
        </button>

        <!-- 🚀 INJECTION DU CENTRE DE NOTIFICATIONS AUTONOME & PARTAGÉ -->
        <app-notification-center></app-notification-center>
      </div>
    </header>

    <!-- Zone d'injection principale pour les formulaires et listes -->
    <div class="content-body">
      <router-outlet></router-outlet>
    </div>
  </main>

  <!-- 🎛️ MODAL COPIÉE DE L'ATS KANBAN - EN SURIMPRESSION AU PREMIER PLAN -->
  <div *ngIf="selectedDirectCandidate" class="modal-overlay" (click)="closeModal()">
    <div class="modal-content recruiter-modal-content" (click)="$event.stopPropagation()">
        
        <!-- En-tête -->
        <div class="modal-header">
          <h3>Candidature de {{ selectedDirectCandidate.name }}</h3>
          <button class="close-btn" (click)="closeModal()">&times;</button>
        </div>

        <!-- Corps des détails avec intégration de l'avatar -->
        <div class="modal-body">
          <div class="candidate-top-row">
            <div class="candidate-photo-block">
              <div class="candidate-avatar">
                <img [src]="selectedDirectCandidate.avatar_logo ? assetsUrl + '/logos/' + selectedDirectCandidate.avatar_logo : 'assets/images/default-avatar.png'" 
                     (error)="$any($event.target).src='assets/images/default-avatar.png'"
                     alt="Photo du candidat">
              </div>
              <button (click)="openCandidateCV(selectedDirectCandidate.candidate_id)"
                      [disabled]="!selectedDirectCandidate.cv_summary || selectedDirectCandidate.cv_summary.trim() === ''"
                      [class.disabled-button]="!selectedDirectCandidate.cv_summary || selectedDirectCandidate.cv_summary.trim() === ''"
                      class="btn-cv-view">
                <svg xmlns="http://www.w3.org/2000/svg" width="11" height="11" fill="currentColor" viewBox="0 0 16 16">
                  <path d="M14 14V4.5L9.5 0H4a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h8a2 2 0 0 0 2-2M9.5 1A1.5 1.5 0 0 1 11 2.5V4h3v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1z"/>
                </svg>
                {{ selectedDirectCandidate.cv_summary && selectedDirectCandidate.cv_summary.trim() !== '' ? 'Consulter le CV' : 'Aucun CV' }}
              </button>
            </div>

            <div class="candidate-summary-grid">
              <div class="candidate-detail-item">
                <span class="detail-label">Poste ciblé :</span>
                <span class="detail-value">{{ selectedDirectCandidate.job_title }}</span>
              </div>
              <div class="candidate-detail-item">
                <span class="detail-label">Date candidature :</span>
                <span class="detail-value">{{ selectedDirectCandidate.applied_at ? (selectedDirectCandidate.applied_at | date:'dd/MM/yyyy à HH:mm') : '—' }}</span>
              </div>
              <div class="candidate-detail-item">
                <span class="detail-label">Adresse e-mail :</span>
                <span class="detail-value">{{ selectedDirectCandidate.email }}</span>
              </div>
              <div class="candidate-detail-item">
                <span class="detail-label">Téléphone :</span>
                <span class="detail-value">{{ selectedDirectCandidate.phone || 'Non renseigné' }}</span>
              </div>
            </div>
          </div>

          <div class="candidate-detail-grid">
            <div class="candidate-detail-item">
              <span class="detail-label">Ville / Région :</span>
              <span class="detail-value">{{ selectedDirectCandidate.address || 'Non spécifiée' }}</span>
            </div>
            <div class="candidate-detail-item">
              <span class="detail-label">Contrat souhaité :</span>
              <span class="detail-value">{{ selectedDirectCandidate.job_type || 'Non renseigné' }}</span>
            </div>
            <div class="candidate-detail-item">
              <span class="detail-label">Situation actuelle :</span>
              <span class="detail-value">{{ selectedDirectCandidate.job_status || 'Non renseignée' }}</span>
            </div>
            <div class="candidate-detail-item">
              <span class="detail-label">Date de naissance :</span>
              <span class="detail-value">{{ selectedDirectCandidate.birth_date ? (selectedDirectCandidate.birth_date | date:'dd/MM/yyyy') : 'Non renseignée' }}</span>
            </div>
            <div class="candidate-detail-item">
              <span class="detail-label">Disponibilité :</span>
              <span class="detail-value">{{ selectedDirectCandidate.availability || 'Non renseignée' }}</span>
            </div>
            <div class="candidate-detail-item">
              <span class="detail-label">Réseaux :</span>
              <span class="detail-value">
                <ng-container *ngIf="selectedDirectCandidate.linkedin && selectedDirectCandidate.linkedin.trim() !== ''">
                  <a [href]="selectedDirectCandidate.linkedin" target="_blank">LinkedIn</a>
                </ng-container>
                <ng-container *ngIf="selectedDirectCandidate.github && selectedDirectCandidate.github.trim() !== ''">
                  <span class="network-separator">|</span>
                  <a [href]="selectedDirectCandidate.github" target="_blank">GitHub</a>
                </ng-container>
                <span *ngIf="(!selectedDirectCandidate.linkedin || selectedDirectCandidate.linkedin.trim() === '') && (!selectedDirectCandidate.github || selectedDirectCandidate.github.trim() === '')" class="detail-empty">Non renseigné</span>
              </span>
            </div>
          </div>

          <!-- Boîte du Résumé -->
          <div class="summary-box" style="margin-top: 15px; padding: 16px; background: #f8fafc; border-radius: 8px; border-left: 4px solid #0ea5e9;">
            <span class="summary-title" style="color: #0f172a; font-weight: 700; font-size: 13px; display: block; margin-bottom: 8px;">
              Résumé du profil & Compétences clés
            </span>
            <p class="summary-text" style="margin: 0; color: #475569; font-size: 13px; line-height: 1.6; white-space: pre-line;">
              {{ selectedDirectCandidate.cv_summary || "Le candidat n'a pas encore rédigé de présentation de profil sur son espace TunJob." }}
            </p>
          </div>

          @if (selectedDirectCandidate.has_quiz) {
            <details class="notif-quiz-accordion" style="margin-top: 14px;" open>
              <summary class="notif-quiz-summary">
                <span><i class="bi bi-patch-question-fill"></i> Réponses au quiz</span>
                <span class="quiz-title-inline">{{ selectedDirectCandidate.quiz_title || 'Quiz de présélection' }}</span>
              </summary>

              @if (selectedDirectCandidate.quiz_answers?.length) {
                <div class="notif-quiz-list">
                  @for (answer of selectedDirectCandidate.quiz_answers; track answer.question_id; let i = $index) {
                    <div class="notif-quiz-item" [class.correct]="answer.is_correct" [class.incorrect]="!answer.is_correct">
                      <div class="notif-quiz-question">
                        <span class="notif-quiz-number">Q{{ i + 1 }}</span>
                        {{ answer.question_text }}
                      </div>
                      <div class="notif-quiz-answer">
                        {{ answer.selected_choice_text }}
                      </div>
                    </div>
                  }
                </div>
              } @else {
                <p class="notif-quiz-empty">Aucune réponse quiz disponible pour cette candidature.</p>
              }
            </details>
          }
        </div>

        <!-- 🔘 PIED DE PAGE INTERACTIF DU KANBAN MODAL -->
        <div class="modal-footer" style="display: flex !important; align-items: center !important; justify-content: space-between !important; gap: 20px !important; margin-top: 25px; border-top: 1px solid #f1f5f9; padding-top: 16px; width: 100% !important; box-sizing: border-box !important;">
          <div style="display: flex !important; gap: 8px !important; flex-wrap: wrap !important; flex-grow: 1 !important;">
            <button (click)="changeCandidateStatus(selectedDirectCandidate.application_id, 'Proposition')" style="background: #10b981; color: white; border: none; padding: 8px 12px; border-radius: 5px; font-size: 12px; font-weight: 600; cursor: pointer; display: flex; align-items: center; gap: 5px;">Accepter</button>
            <button (click)="changeCandidateStatus(selectedDirectCandidate.application_id, 'Nouveau')" style="background: #64748b; color: white; border: none; padding: 8px 12px; border-radius: 5px; font-size: 12px; font-weight: 600; cursor: pointer; display: flex; align-items: center; gap: 5px;">En attente</button>
            <button (click)="changeCandidateStatus(selectedDirectCandidate.application_id, 'Entretien')" style="background: #f97316; color: white; border: none; padding: 8px 12px; border-radius: 5px; font-size: 12px; font-weight: 600; cursor: pointer; display: flex; align-items: center; gap: 5px;">Entretien</button>
            <button (click)="changeCandidateStatus(selectedDirectCandidate.application_id, 'Rejete')" style="background: #ef4444; color: white; border: none; padding: 8px 12px; border-radius: 5px; font-size: 12px; font-weight: 600; cursor: pointer; display: flex; align-items: center; gap: 5px;">Rejeter</button>
          </div>
          <button class="btn-secondary" (click)="closeModal()" style="padding: 8px 16px !important; font-size: 12px !important; font-weight: 600 !important; cursor: pointer !important; flex-shrink: 0 !important; margin: 0 !important;">Fermer</button>
        </div>

    </div>
  </div>

</div>
